export function coverageCounts(tools = calculatorNetTools) {
  const count = (status) => tools.filter((item) => item.status === status).length;
  const covered = count('covered');
  const added = count('added');
  const partial = count('partial');
  const remaining = count('remaining');
  const blocked = count('blocked');
  const directory = count('directory');
  return {
    sitemapLocs: calculatorNetExcluded.length + tools.length,
    excluded: calculatorNetExcluded.length,
    classifiedTools: tools.length,
    directory,
    formulaTools: tools.length - directory,
    covered,
    added,
    partial,
    remaining,
    blocked,
    stillMissing: partial + remaining + blocked
  };
}

